class LoadScfFileModal(ConfirmationModal):

    def wait_until_load_file_modal_appear(self, timeout=60):
        self.wait_until_modal_appear(self.locator.MODAL_LOAD_XPATH, timeout)

    def execute(self, validate_plan, timeout=60):
        self.verify_toast_message(validate_plan=validate_plan, timeout=timeout)
        try:
            status = self.get_text(self.locator.TOAST_MESSAGE_CONTAINER, timeout)
            if "finished" in status:
                return self.check_if_load_commissioning_is_successful()
            return status
        except Exception as e:
            logging.debug(" Failed to catch toast message due to {}".format(e))

    def verify_toast_message(self, validate_plan, timeout=60):
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Load SCF operation started"), timeout)
        if validate_plan:
            self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Validate plan operation started"), timeout)
            self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Validate plan operation finished"), timeout)
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("Load SCF operation finished"), timeout)

    def check_if_load_commissioning_is_successful(self, timeout=10):
        if self.element_exists(self.locator.LOAD_COMMISSIONING_SUCCESS_XPATH, timeout):
            return "Load SCF operation has succeeded"

    def confirm(self, timeout=60):
        self.click_enabled_element(self.locator.CLOSE_BUTTON_XPATH, timeout)

    def check_status_after_loading_scf_file(self, validate_plan, timeout=60):
        """
        Check status after loading scf file
        """
        load_scf_nodes = 4
        if not validate_plan:
            load_scf_nodes = 3
        load_scf_file_node_status_xpath = '//span[contains(@class, "steps-number")][contains(text(),{})]'
        for index in range(1, load_scf_nodes + 1):
            node_status_xpath = load_scf_file_node_status_xpath.format(index)
            node_status = self.get_attribute_by_xpath(node_status_xpath.format(index), "class", timeout)
            if "failed" in node_status:
                return False
        return True


