class ActivatePlanModal(ConfirmationModal):
    """
    Class for activate plan modal, providing methods to manipulate elements on modal
    """

    def wait_until_activate_plan_modal_appear(self, timeout=60):
        self.wait_until_modal_appear(self.locator.MODAL_XPATH, timeout)

    def close(self, status, timeout=60):
        if "failed" in status:
            self.click_enabled_element(self.locator.CLOSE_BUTTON_XPATH, timeout)
        else:
            self.click_enabled_element(self.locator.DONE_BUTTON_XPATH, timeout)

    def execute(self, is_download, timeout=900):
        self.click_enabled_element(self.locator.EXECUTE_BUTTON_XPATH, timeout)
        self.check_toast_message(is_download)
        return self.check_if_activate_successfully(timeout)

    def check_toast_message(self, message):
        message = "Download" if message else "Activate"
        self.wait_for_visibility(self.locator.TOAST_MESSAGE.format("{} plan operation started".format(message)))
        self.wait_for_invisibility(self.locator.TOAST_MESSAGE.format("{} plan operation started".format(message)))

    def select_download_plan_without_activation(self, timeout=60):
        self.click_enabled_element(self.locator.DOWNLOAD_PLAN_CHECKBOX, timeout)

    def select_activate_plan_despite_reset(self, timeout=60):
        if self.element_exists(self.locator.ACTIVATE_PLAN_DESPITE_RESET_XPATH, timeout):
            self.click_enabled_element(self.locator.ACTIVATE_PLAN_DESPITE_RESET_XPATH, timeout)

    def select_activate_plan_despite_cell_locking(self, timeout=60):
        if self.element_exists(self.locator.ACTIVATE_PLAN_DESPITE_CELL_LOCKING_XPATH, timeout):
            self.click_enabled_element(self.locator.ACTIVATE_PLAN_DESPITE_CELL_LOCKING_XPATH, timeout)

    def check_if_activate_successfully(self, timeout=10):
        if self.element_exists(self.locator.PLAN_ACTIVATION_STATUS, timeout):
            return "Plan activation has finished successfully"
        elif self.element_exists(self.locator.DOWNLOAD_OPERATION_STATUS):
            return "Download operation has succeeded"
        else:
            feedback = self.get_text(self.locator.PLAN_ACTIVATION_FEEDBACK_TEXT)
            return "Plan activation failed {}".format(feedback)


