class SaveBtsConfigurationModal(ConfirmationModal):

    def wait_until_save_bts_configuration_modal_appear(self, timeout=60):
        self.wait_until_modal_appear(self.locator.SAVE_CONFIGURATION_MODAL_CLASS, timeout)

    def save(self, save_configuration_type_str, timeout):
        save_status = self._set_save_configuration_type(save_configuration_type_str)
        if save_status:
            self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        else:
            self.cancel()
            raise ElementIsDisable(
                "selected save configuration type is disabled, please select the plan accordingly to save SCF")

    def cancel(self, timeout=60):
        self.click_enabled_element(self.locator.CANCEL_BUTTON_XPATH, timeout)

    def _set_save_configuration_type(self, save_configuration_type_str):
        if self.element_exists(self.locator.SAVE_CONFIGURATION_TYPE_MAIN_XPATH.
                               format('BTS configuration')):
            self.click_element_by_xpath(self.locator.SAVE_CONFIGURATION_TYPE_MAIN_XPATH.
                                        format('BTS configuration'))
        for conf_type in save_configuration_type_str.split(","):
            self.click_element_by_xpath(self.locator.SAVE_CONFIGURATION_TYPE_MAIN_XPATH.
                                        format(conf_type))
            if not self.element_exists(self.locator.SAVE_CONFIG_XPATH.format(conf_type)):
                return False
        return True


class ValidationErrorsModal(ConfirmationModal):

    def wait_until_validation_errors_modal(self, timeout=2):
        try:
            self.wait_until_modal_appear(self.locator.MODAL_XPATH, timeout)
        except TimeoutException:
            logging.warning("No validation errors modal is found")

    def close(self, timeout=1):
        try:
            self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        except TimeoutException:
            logging.warning("wait validation errors modal timeout")
        except NoSuchElementException:
            logging.warning("validation errors modal is not exist")


class CopyObjectModel(ConfirmationModal):
    def wait_until_copy_object_modal_appear(self, timeout=60):
        self.wait_until_modal_appear(self.locator.COPY_OBJECT_TITLE_XPATH, timeout)

    def copy_object(self, object_class_name, plan_name, object_distinguished_name, copy_object_with_subtree, id_value,
                    timeout):
        self.click_enabled_element(self.locator.COPY_OBJECT_TITLE_XPATH)
        self.click_enabled_element(self.locator.OBJECT_CLASS_DROP_DOWN_XPATH)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(object_class_name))
        self.click_enabled_element(self.locator.PLAN_DROP_DOWN_XPATH)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(plan_name))
        self.click_enabled_element(self.locator.OBJECT_DISTINGUISHED_NAME_DROP_DOWN_XPATH)
        self.click_enabled_element(self.locator.CHOOSE_ITEM_FROM_DROP_DOWN.format(object_distinguished_name))
        if copy_object_with_subtree:
            self.select_radiobox(self.locator.COPY_OBJECT_WITH_SUBTREE_CHECKBOX_XPATH, timeout)
        if id_value:
            self.insert_text_to_enable_element(self.locator.COPY_OBJECT_INPUT_ID, id_value, timeout)

    def submit(self, timeout=60):
        self.click_enabled_element(self.locator.OK_BUTTON_XPATH, timeout)
        self.wait_until_modal_appear(self.locator.TOAST_MESSAGE.format('Copy object operation finished'),
                                     timeout)


